{"content":"<js>(function(){
var html=String(result);
var m=html.match(/params\s*=\s*'([^']+)'/);
if(!m){return ''}
var raw=Packages.java.util.Base64.getDecoder().decode(m[1]);
var iv=Packages.java.util.Arrays.copyOfRange(raw,0,16);
var ct=Packages.java.util.Arrays.copyOfRange(raw,16,raw.length);
var key=new Packages.java.lang.String('5V&RoR%Jf@pJPydF').getBytes('UTF-8');
var c=Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
c.init(Packages.javax.crypto.Cipher.DECRYPT_MODE,new Packages.javax.crypto.spec.SecretKeySpec(key,'AES'),new Packages.javax.crypto.spec.IvParameterSpec(iv));
var d=JSON.parse(new Packages.java.lang.String(c.doFinal(ct),'UTF-8'));
if(d.comic_status&&d.comic_status!=='normal'){return ''}
var arr=d.chapter_images||[];
var host=(d.images_hosts&&d.images_hosts[0])||'';
var USE_PROXY=false;
var out=[];
for(var i=0;i<arr.length;i++){
var u=String(arr[i]);
if(USE_PROXY&&host){
u=host+'/'+Packages.java.util.Base64.getEncoder().encodeToString(new Packages.java.lang.String(u).getBytes('UTF-8'));
}
out.push('<img src="'+u+'"/>');
}
return out.join('\n');
})()</js>","imageStyle":"max-width:100%;height:auto;"}

